usage.code:
import { InfiniteSpiral } from "solen-design/react";

const images = [
  { src: "/images/landscape-1.jpg", alt: "Mountain lake" },
  { src: "/images/landscape-2.jpg", alt: "Forest path" },
];

export default function App() {
  return (
    <div style={{ height: 600 }}>
      <InfiniteSpiral items={images} animationMode="all" />
    </div>
  );
}

import { InfiniteSpiral } from "solen-design/solid";

export default function App() {
  return (
    <div style={{ height: "600px" }}>
      <InfiniteSpiral items={images} animationMode="all" />
    </div>
  );
}

import { InfiniteSpiral } from "solen-design/preact";

export default function App() {
  return (
    <div style={{ height: 600 }}>
      <InfiniteSpiral items={images} animationMode="all" />
    </div>
  );
}

import { mountInfiniteSpiral } from "solen-design/vanilla";

const target = document.querySelector<HTMLElement>("#demo")!;
const component = mountInfiniteSpiral(target, { items: images, animationMode: "all" });

